def attribuer_prestataire_aux_menus(apps, schema_editor):
    """
    Menus existants : prestataire déduit sans ambiguïté
      1. de leurs plats (tous les plats d'un prestataire sont du même) ;
      2. sinon du compte qui a créé le menu (compte de l'espace prestataire).
    Plats de plusieurs prestataires, ou menus d'UbiPharm : laissés vides
    (regroupés sous « Cantine UbiPharm », facturés comme avant).
    """
    Menu = apps.get_model('api', 'Menu')
    MenuPlat = apps.get_model('api', 'MenuPlat')
    par_menu = {}
    for menu_id, prest_id in MenuPlat.objects.values_list('menu_id', 'plat__prestataire_id'):
        par_menu.setdefault(menu_id, set()).add(prest_id)
    for menu in Menu.objects.filter(prestataire__isnull=True).select_related('user_created'):
        prests = par_menu.get(menu.id, set())
        avec = prests - {None}
        prestataire_id = None
        if len(avec) == 1:
            prestataire_id = next(iter(avec))
        elif not avec and menu.user_created_id and menu.user_created.prestataire_id:
            prestataire_id = menu.user_created.prestataire_id
        if prestataire_id:
            Menu.objects.filter(pk=menu.pk).update(prestataire_id=prestataire_id)


